    fn write_u64(&mut self, value: u64) { self.0 = value; }
    fn write(&mut self, bytes: &[u8]) {
        let mut hasher = SmeltFieldHasher(self.0);
        ::std::hash::Hasher::write(&mut hasher, bytes);
        self.0 = ::std::hash::Hasher::finish(&hasher);
    }
